    TaskRecord task;task.id="task:1";task.assignee="recipient";task.status="active";f.tasks.tasks.insert(task.id,task);need(!f.propose("recipient").value&&!visit_reception_conversation_ready(f.read(),f.director,"recipient","recipient_intent").value,"accepted responsibility prevents reception override");f.tasks.tasks.erase(task.id);f.adopt(f.next("recipient","dialogue_next"));f.adopt(f.next("recipient","dialogue_choose"));f.adopt(f.next("recipient","receive_visit_message"));need(f.messages.received.size()==1,"real provider declaration delivers original recipient fact");auto end=f.next("recipient","end_interaction");need(end.transition->goal_ref==original_goal,"End proposal retains claim until actual success");f.adopt(end);need(validate_visit_messages(f.common,f.messages,f.messages_catalog,f.dialogues).ok,"original full message cold validation remains valid");
